	(112, 15, 'assistant', '{"message":"죄송해요, 잠시 문제가 생겼어요. 아래 링크를 이용해보세요! 🙏","inappropriate":false,"links":[{"label":"여행지 탐색","url":"/explore","icon":"📍"},{"label":"AI 도우미","url":"/assistant","icon":"✨"},{"label":"커뮤니티","url":"/community/list","icon":"💬"},{"label":"강원도 관련 패키지 둘러보기","url":"/packages","icon":"🎁"}],"quickReplies":["인기 여행지 추천","여행 코스 보기"]}', 0, '2026-04-23 19:16:42'),
	(113, 21, 'user', '경복궁이요', 0, '2026-04-23 22:12:29'),
	(114, 21, 'assistant', '{"message":"경복궁에 관심 있으시군요! 🤩 경복궁 상세 페이지에서 다양한 정보를 확인해 보세요! 아직 리뷰는 없지만, 방문 후 첫 리뷰를 남겨주시는 건 어떠세요?","inappropriate":false,"links":[{"label":"경복궁 상세 보기","url":"/detail/27","icon":"🏰"},{"label":"다른 여행지 탐색","url":"/explore","icon":"✈️"}],"quickReplies":["경복궁 관련 여행 코스","다른 인기 여행지는 어디야?"]}', 0, '2026-04-23 22:12:35'),
	(115, 26, 'user', '제주도에 가고 싶어. 추천좀 해줘.', 0, '2026-04-24 04:05:00'),
	(116, 26, 'assistant', '{"message":"제주도는 정말 멋진 선택이에요! ✨ 트립투게더에는 한국의 보석 같은 섬, 제주도에 대한 정보가 가득하답니다. 한라산, 성산일출봉, 우도 등 아름다운 자연과 독특한 문화를 탐험해보세요!","inappropriate":false,"links":[{"label":"제주도 자세히 보기","url":"/detail/8","icon":"🏝️"},{"label":"다른 여행지 탐색하기","url":"/explore","icon":"🔍"},{"label":"다양한 여행 코스 둘러보기","url":"/courses","icon":"🗺️"},{"label":"로그인하고 더 많은 기능 이용하기","url":"/auth/login","icon":"🔑"},{"label":"제주도 관련 패키지 둘러보기","url":"/packages","icon":"🎁"}],"quickReplies":["다른 여행지도 추천해줘!","제주도 여행 코스는 없어?","로그인하면 뭐가 좋아?"]}', 0, '2026-04-24 04:05:08'),
	(117, 27, 'user', 'asfd', 1, '2026-04-25 22:09:34'),
	(118, 27, 'assistant', '{"message":"해당 질문에는 답변하기 어려워요. 여행 관련 질문으로 다시 물어봐 주세요.","inappropriate":true,"links":[],"quickReplies":["인기 여행지 추천","여행 코스 보기"]}', 0, '2026-04-25 22:09:35'),
	(119, 10, 'user', '제주도 여행지에 대해 안내해줘', 0, '2026-04-28 08:32:08'),
	(120, 10, 'assistant', '{"message":"죄송해요, 잠시 문제가 생겼어요. 아래 링크를 이용해보세요! 🙏","inappropriate":false,"links":[{"label":"여행지 탐색","url":"/explore","icon":"📍"},{"label":"AI 도우미","url":"/assistant","icon":"✨"},{"label":"커뮤니티","url":"/community/list","icon":"💬"}],"quickReplies":["인기 여행지 추천","여행 코스 보기"]}', 0, '2026-04-28 08:32:16'),
	(121, 28, 'user', '제주도 여행지에 대해 안내해줘', 0, '2026-04-28 08:32:26'),
	(122, 28, 'assistant', '{"message":"죄송해요, 잠시 문제가 생겼어요. 아래 링크를 이용해보세요! 🙏","inappropriate":false,"links":[{"label":"여행지 탐색","url":"/explore","icon":"📍"},{"label":"AI 도우미","url":"/assistant","icon":"✨"},{"label":"커뮤니티","url":"/community/list","icon":"💬"}],"quickReplies":["인기 여행지 추천","여행 코스 보기"]}', 0, '2026-04-28 08:32:31'),
	(123, 28, 'user', '인기 여행지 추천', 0, '2026-04-28 08:32:53'),
	(124, 28, 'assistant', '{"message":"죄송해요, 잠시 문제가 생겼어요. 아래 링크를 이용해보세요! 🙏","inappropriate":false,"links":[{"label":"여행지 탐색","url":"/explore","icon":"📍"},{"label":"AI 도우미","url":"/assistant","icon":"✨"},{"label":"커뮤니티","url":"/community/list","icon":"💬"},{"label":"여행지 관련 패키지 둘러보기","url":"/packages","icon":"🎁"}],"quickReplies":["인기 여행지 추천","여행 코스 보기"]}', 0, '2026-04-28 08:33:01'),
	(125, 23, 'user', '제주도 여행지 추천해줘', 0, '2026-04-28 11:39:34'),
	(126, 23, 'assistant', '{"message":"와, 제주도는 정말 최고의 선택이에요! ✨ 한국의 보석 같은 섬 제주도에서 아름다운 자연과 독특한 문화를 만끽해 보세요. 제주도에 대한 더 자세한 정보를 확인해 보세요!","inappropriate":false,"links":[{"label":"제주도 상세 정보","url":"/detail/8","icon":"🏝️"},{"label":"제주도 3박 4일 코스","url":"/courses/detail?planId=3","icon":"🗓️"},{"label":"다른 여행지 찾아보기","url":"/explore","icon":"🔍"}],"quickReplies":["제주도 숙소는?","AI가 제주도 코스 짜줄 수 있어?","다른 국내 여행지 추천해줘"]}', 0, '2026-04-28 11:39:41');
INSERT INTO `COMMUNITY_COMMENT` (`comment_id`, `post_id`, `user_idx`, `content`, `ip_address`, `comment_status`, `like_count`, `created_at`, `updated_at`, `parent_comment_id`, `report_count`, `ai_flagged`) VALUES
	(1, 1, 7, '저도 작년에 다녀왔는데 철학의 길 정말 최고였어요! 아침 일찍 가면 사람이 적어서 더 좋습니다.', '220.85.67.43', 'ACTIVE', 0, '2026-03-12 11:30:00', '2026-03-12 11:30:00', NULL, 0, 0),
	(2, 1, 9, '숙소 예약 팁 감사합니다! 6개월 전이면 10월에 예약해야겠네요.', '110.47.22.88', 'ACTIVE', 0, '2026-03-12 13:00:00', '2026-03-12 13:00:00', NULL, 0, 0),
	(3, 1, 2, '맞아요! 6시쯤 가면 아무도 없어서 완전 혼자 즐길 수 있어요.', '175.112.34.21', 'ACTIVE', 0, '2026-03-12 12:00:00', '2026-03-12 12:00:00', 1, 0, 0),
	(4, 1, 12, '저는 4개월 전에 예약했는데 간신히 구했어요. 인기 시즌엔 정말 빨리 차더라고요.', '58.231.101.14', 'ACTIVE', 0, '2026-03-12 14:00:00', '2026-03-12 14:00:00', 2, 0, 0),
	(5, 2, 12, '몽마르트 언덕 올라가는 길 오른쪽에 할머니가 운영하는 가게 혹시 알아요? 거기가 진짜였는데.', '58.231.101.14', 'ACTIVE', 0, '2026-03-14 14:00:00', '2026-03-14 14:00:00', NULL, 0, 0),
	(6, 2, 13, '누텔라+바나나 크레이프가 진짜 맛있었어요. 버터+설탕이 더 나은가요?', '211.36.145.77', 'ACTIVE', 0, '2026-03-14 15:30:00', '2026-03-14 15:30:00', NULL, 0, 0),
	(7, 2, 7, '네 맞아요! 계단 중간쯤에 있는 파란 간판 작은 가게요. 거기 정말 맛있죠.', '220.85.67.43', 'ACTIVE', 0, '2026-03-14 14:45:00', '2026-03-14 14:45:00', 5, 0, 0),
	(8, 2, 2, '개인 취향이지만 심플한 게 크레이프 자체 맛을 더 느낄 수 있어서 추천합니다!', '175.112.34.21', 'ACTIVE', 0, '2026-03-14 16:00:00', '2026-03-14 16:00:00', 6, 0, 0),
	(9, 3, 13, '덤보(DUMBO) 쪽에서 찍는 사진도 진짜 유명하죠! 거기도 추천드려요.', '211.36.145.77', 'ACTIVE', 0, '2026-03-16 10:30:00', '2026-03-16 10:30:00', NULL, 0, 0),
	(10, 3, 2, '골든아워 시간대가 몇 시쯤인가요? 계절마다 다르겠지만 3월 기준으로 알고 싶어요.', '175.112.34.21', 'ACTIVE', 0, '2026-03-16 11:00:00', '2026-03-16 11:00:00', NULL, 0, 0),
	(11, 3, 9, '덤보 맞아요! 맨해튼 브릿지 아치 사이로 브루클린 브릿지 찍히는 각도 완전 유명하죠.', '110.47.22.88', 'ACTIVE', 0, '2026-03-16 11:00:00', '2026-03-16 11:00:00', 9, 0, 0),
	(12, 3, 9, '3월은 오후 6시~7시 사이가 제일 예뻐요. 날씨 맑은 날 골라가세요!', '110.47.22.88', 'ACTIVE', 0, '2026-03-16 11:30:00', '2026-03-16 11:30:00', 10, 0, 0),
	(13, 4, 2, '이민국 방문 해봤는데요, 차암 이민국이 비교적 빠릅니다. 30일 연장에 1,900바트입니다. 아침 일찍 가면 당일 처리 돼요.', '175.112.34.21', 'ACTIVE', 0, '2026-03-18 15:00:00', '2026-03-18 15:00:00', NULL, 0, 0),
	(14, 4, 7, '비자런은 말레이시아 페낭이 많이들 가더라고요. 하지만 이민국 방문이 더 안전하고 확실합니다.', '220.85.67.43', 'ACTIVE', 0, '2026-03-18 15:30:00', '2026-03-18 15:30:00', NULL, 0, 0),
	(15, 4, 12, '아 1,900바트군요! 생각보다 비싸지 않네요. 이민국으로 가겠습니다. 감사해요!', '58.231.101.14', 'ACTIVE', 0, '2026-03-18 16:00:00', '2026-03-18 16:00:00', 13, 0, 0),
	(16, 4, 9, '페낭 비자런 저도 해봤는데 왕복 교통비+숙박 생각하면 이민국 방문이 훨씬 이득이에요.', '110.47.22.88', 'ACTIVE', 0, '2026-03-18 16:30:00', '2026-03-18 16:30:00', 14, 0, 0),
	(17, 5, 9, '라보카 지구는 낮에만 가는 게 안전하다고 들었는데 밤에 쇼 보러 가도 괜찮았나요?', '110.47.22.88', 'ACTIVE', 0, '2026-03-21 19:30:00', '2026-03-21 19:30:00', NULL, 0, 0),
	(18, 5, 2, '탱고 배우는 클래스도 있나요? 여행 중에 직접 배워보고 싶어서요.', '175.112.34.21', 'ACTIVE', 0, '2026-03-21 20:00:00', '2026-03-21 20:00:00', NULL, 0, 0),
	(19, 5, 13, '쇼 공연장은 대로변에 있어서 택시로 바로 이동하면 괜찮아요. 늦은 밤 골목은 피하는 게 좋습니다.', '211.36.145.77', 'ACTIVE', 0, '2026-03-21 20:30:00', '2026-03-21 20:30:00', 17, 0, 0),
	(20, 5, 13, '네 있어요! 팔레르모 지구에 입문자용 1시간 클래스가 많습니다. 30~40달러 정도예요.', '211.36.145.77', 'ACTIVE', 0, '2026-03-21 20:45:00', '2026-03-21 20:45:00', 18, 0, 0),
	(21, 6, 7, '공감합니다. 낙타 타는 거 그냥 도와줬다고 나중에 돈 요구하는 경우도 있었어요.', '220.85.67.43', 'ACTIVE', 0, '2026-03-24 10:30:00', '2026-03-24 10:30:00', NULL, 0, 0),
	(22, 6, 12, '여행사 투어 비용이 얼마나 되나요? 개인 투어 대비 얼마나 차이 나는지 궁금합니다.', '58.231.101.14', 'ACTIVE', 0, '2026-03-24 11:00:00', '2026-03-24 11:00:00', NULL, 0, 0),
	(23, 6, 2, '맞아요 무조건 가격 먼저 협의하고 서비스 받아야 합니다. 호의처럼 보여도 다 돈 요구합니다.', '175.112.34.21', 'ACTIVE', 0, '2026-03-24 11:15:00', '2026-03-24 11:15:00', 21, 0, 0),
	(24, 6, 2, '당일 피라미드 투어가 보통 30~50달러 선이에요. 개인으로 가면 비슷하거나 더 비쌀 수도 있어요.', '175.112.34.21', 'ACTIVE', 0, '2026-03-24 11:30:00', '2026-03-24 11:30:00', 22, 0, 0),
	(25, 7, 9, '저는 80유로가 아까워서 수상버스(바포레토) 타고 대운하 구경했어요. 그것도 꽤 분위기 있더라고요.', '110.47.22.88', 'ACTIVE', 0, '2026-03-27 18:30:00', '2026-03-27 18:30:00', NULL, 0, 0),
	(26, 7, 13, '저도 탔는데 곤돌라 사공 아저씨가 노래 불러줘서 완전 감동이었어요ㅋㅋ', '211.36.145.77', 'ACTIVE', 0, '2026-03-27 19:00:00', '2026-03-27 19:00:00', NULL, 0, 0),
	(27, 7, 7, '바포레토도 좋지만 좁은 골목 운하는 곤돌라만 갈 수 있어서 경험 자체가 달라요!', '220.85.67.43', 'ACTIVE', 0, '2026-03-27 19:15:00', '2026-03-27 19:15:00', 25, 0, 0),
	(28, 7, 2, '노래 서비스는 추가 요금 내야 하는 경우도 있다고 들었는데 공짜였나요?ㅎㅎ', '175.112.34.21', 'ACTIVE', 0, '2026-03-27 19:30:00', '2026-03-27 19:30:00', 26, 0, 0),
	(29, 8, 12, '사진 너무 예쁘다! 투어 업체 이름이 어디였나요? 저도 6월에 케언즈 가거든요.', '58.231.101.14', 'ACTIVE', 0, '2026-03-29 10:00:00', '2026-03-29 10:00:00', NULL, 0, 0),
	(30, 8, 13, '스노클링 못 하는 사람도 즐길 수 있나요? 수영을 잘 못해서요.', '211.36.145.77', 'ACTIVE', 0, '2026-03-29 10:30:00', '2026-03-29 10:30:00', NULL, 0, 0),
	(31, 8, 9, 'Reef Magic Cruises 이용했어요! 가격 대비 퀄리티 최고였습니다.', '110.47.22.88', 'ACTIVE', 0, '2026-03-29 11:00:00', '2026-03-29 11:00:00', 29, 0, 0),
	(32, 8, 9, '구명조끼 착용하면 수영 못해도 돼요! 수면 위에서만 봐도 산호초 다 보입니다.', '110.47.22.88', 'ACTIVE', 0, '2026-03-29 11:15:00', '2026-03-29 11:15:00', 30, 0, 0),
	(33, 9, 7, '그랩 오토바이 처음엔 무서웠는데 적응되니까 너무 편하고 빠르더라고요. 헬멧은 꼭 쓰세요!', '220.85.67.43', 'ACTIVE', 0, '2026-04-01 12:30:00', '2026-04-01 12:30:00', NULL, 0, 0),
	(34, 9, 2, '현금 결제도 되나요? 카드 등록이 복잡할까봐서요.', '175.112.34.21', 'ACTIVE', 0, '2026-04-01 13:00:00', '2026-04-01 13:00:00', NULL, 0, 0),
	(35, 9, 12, '맞아요 헬멧 제공해줘서 좋아요. 가방은 앞에 안고 타는 게 안전합니다.', '58.231.101.14', 'ACTIVE', 0, '2026-04-01 13:00:00', '2026-04-01 13:00:00', 33, 0, 0),
	(36, 9, 12, '네 현금 결제 가능합니다! 도착 후 기사에게 직접 주면 돼요. 카드 없어도 완전 사용 가능해요.', '58.231.101.14', 'ACTIVE', 0, '2026-04-01 13:15:00', '2026-04-01 13:15:00', 34, 0, 0),
	(37, 10, 9, '세노테 이름이 어디였나요? 칸쿤 주변에 여러 개 있는 걸로 알아서요.', '110.47.22.88', 'ACTIVE', 0, '2026-04-03 11:30:00', '2026-04-03 11:30:00', NULL, 0, 0),
	(38, 10, 7, '수영 못해도 구명조끼로 즐길 수 있나요? 물이 얼마나 깊은지 궁금해서요.', '220.85.67.43', 'ACTIVE', 0, '2026-04-03 12:00:00', '2026-04-03 12:00:00', NULL, 0, 0),
	(39, 10, 13, '이크 카레테! 칸쿤에서 차로 약 2시간이고 투어 상품으로 묶어서 가는 게 편해요.', '211.36.145.77', 'ACTIVE', 0, '2026-04-03 12:15:00', '2026-04-03 12:15:00', 37, 0, 0),
	(40, 10, 13, '구명조끼 제공합니다! 깊이는 세노테마다 다른데 5~10m 정도예요. 무조건 추천합니다.', '211.36.145.77', 'ACTIVE', 0, '2026-04-03 12:30:00', '2026-04-03 12:30:00', 38, 0, 0),
