INSERT INTO `COMMUNITY_POST` (`post_id`, `user_idx`, `title`, `content`, `ip_address`, `created_at`, `region`, `post_type`, `post_status`, `view_count`, `like_count`, `comment_count`, `updated_at`, `report_count`, `is_solved`, `solved_at`, `accepted_comment_id`, `tip_category`, `ai_flagged`) VALUES
	(1, 2, '교토 벚꽃 시즌 완벽 가이드', '3월 말~4월 초 철학의 길과 마루야마 공원은 환상적입니다. 숙소는 최소 6개월 전 예약하지 않으면 구하기 정말 힘듭니다.', '175.112.34.21', '2026-03-12 10:00:00', 'asia', 'review', 'ACTIVE', 2, 0, 4, '2026-04-27 22:31:07', 0, NULL, NULL, NULL, NULL, 0),
	(2, 7, '파리 크레이프 맛집 투어 후기', '몽마르트 언덕 근처 작은 크레이프 가게들이 진짜입니다. 관광지 메뉴판보다 현지인 줄 서있는 곳으로 가세요. 버터+설탕 심플한 게 제일 맛있었습니다.', '220.85.67.43', '2026-03-14 12:00:00', 'europe', 'tip', 'ACTIVE', 0, 0, 4, '2026-04-15 14:55:01', 0, NULL, NULL, NULL, 'food', 0),
	(3, 9, '뉴욕 브루클린 브릿지 포토스팟 총정리', '맨해튼 쪽에서 걸어서 브루클린 방향으로 갈 때 중간 지점이 제일 예쁩니다. 해질녘 골든아워 타임에 가면 다리와 스카이라인이 같이 나옵니다.', '110.47.22.88', '2026-03-16 09:00:00', 'north_america', 'photo', 'ACTIVE', 0, 0, 4, '2026-04-15 14:55:02', 0, NULL, NULL, NULL, NULL, 0),
	(4, 12, '태국 관광비자 연장 직접 해보신 분?', '방콕에서 30일 무비자로 입국했는데 일정이 늘어나서 연장하고 싶습니다. 이민국 직접 방문 vs 비자런 중 어느 게 나을까요?', '58.231.101.14', '2026-03-18 14:00:00', 'asia', 'question', 'ACTIVE', 1, 0, 4, '2026-04-16 08:08:34', 0, 0, NULL, NULL, NULL, 0),
	(5, 13, '부에노스아이레스 탱고 쇼 추천', '라보카 지구 밀롱가에서 본 탱고 쇼는 정말 압도적이었습니다. 길거리 무료 공연도 있지만 실내 정식 쇼가 퀄리티가 훨씬 높습니다. 저녁 8시 공연 추천합니다.', '211.36.145.77', '2026-03-21 18:00:00', 'south_america', 'review', 'ACTIVE', 0, 0, 4, '2026-04-15 14:55:03', 0, NULL, NULL, NULL, NULL, 0),
	(6, 2, '이집트 여행 안전 주의사항 총정리', '피라미드 주변 호객꾼 정말 심합니다. 단호하게 NO라고 말하고 눈 마주치지 마세요. 여행사 투어로 가면 가이드가 막아줘서 훨씬 편합니다.', '175.112.34.21', '2026-03-24 09:00:00', 'africa', 'tip', 'ACTIVE', 0, 0, 4, '2026-04-15 14:55:04', 0, NULL, NULL, NULL, 'safety', 0),
	(7, 7, '베네치아 곤돌라, 탈 가치 있나요?', '솔직히 30분에 80유로 비쌉니다. 하지만 좁은 운하를 미끄러지듯 지나가는 그 경험은 돈 주고 사는 낭만이었습니다. 일몰 전후 타는 걸 추천합니다.', '220.85.67.43', '2026-03-27 17:00:00', 'europe', 'review', 'ACTIVE', 1, 0, 4, '2026-04-19 15:05:36', 0, NULL, NULL, NULL, NULL, 0),
	(8, 9, '그레이트배리어리프 스노클링 사진 모음', '케언즈에서 당일치기 투어로 다녀왔습니다. 물속에서 직접 찍은 산호초와 열대어 사진들입니다. 방수 카메라 필수! 투어 업체에서 대여도 가능합니다.', '110.47.22.88', '2026-03-29 08:00:00', 'oceania', 'photo', 'ACTIVE', 2, 0, 4, '2026-04-21 02:35:37', 0, NULL, NULL, NULL, NULL, 0),
	(9, 12, '베트남 그랩 앱 완전 정복', '호치민·하노이·다낭 모두 그랩이 제일 편합니다. 미리 목적지 입력하면 가격 나오고 흥정 불필요. 오토바이 그랩은 더 저렴하고 빠릅니다.', '58.231.101.14', '2026-04-01 11:00:00', 'asia', 'tip', 'ACTIVE', 2, 0, 4, '2026-04-17 07:18:27', 0, NULL, NULL, NULL, 'transport', 0),
	(10, 13, '칸쿤 세노테 투어 강력 추천', '멕시코 유카탄 반도의 숨겨진 보석, 세노테. 지하 석회암 동굴에 고인 맑은 물에서 수영하는 경험은 카리브해 바다와는 또 다른 감동입니다.', '211.36.145.77', '2026-04-03 10:00:00', 'north_america', 'review', 'ACTIVE', 0, 0, 4, '2026-04-15 14:55:06', 0, NULL, NULL, NULL, NULL, 0),
	(11, 2, '여권 만료 3개월 남은 상태로 일본 입국 가능한가요?', '5월에 일본 가려는데 여권 유효기간이 8월 말까지예요. 일본은 잔여기간 조건이 어떻게 되나요? 재발급 받아야 할까요?', '175.112.34.21', '2026-04-05 09:00:00', 'etc', 'question', 'ACTIVE', 11, 0, 4, '2026-04-25 22:42:57', 0, 0, NULL, NULL, NULL, 0),
	(12, 7, '콜롬비아 메데진 호스텔 추천 및 주의사항', '엘포블라도 지구 호스텔이 가성비 좋습니다. 도미토리 기준 1박 15~20달러. 단 귀중품 사물함 잠금 철저히 하세요. 한국인 여행자 많아서 정보 공유 편합니다.', '220.85.67.43', '2026-04-07 14:00:00', 'south_america', 'tip', 'ACTIVE', 3, 0, 4, '2026-04-16 08:42:02', 0, NULL, NULL, NULL, 'accom', 0),
	(13, 9, '융프라우요흐 정상 설원 사진 모음', '유럽의 지붕 해발 3454m. 맑은 날 가야 알프스 전경이 보입니다. 가는 날 날씨 꼭 확인하세요. 정상은 여름에도 춥기 때문에 패딩 챙기는 건 필수입니다.', '110.47.22.88', '2026-04-08 07:00:00', 'europe', 'photo', 'ACTIVE', 0, 0, 4, '2026-04-15 14:55:07', 0, NULL, NULL, NULL, NULL, 0),
	(14, 12, '사하라 사막 낙타 트레킹 1박2일 후기', '메르주가 모래 언덕에서 일몰~일출까지. 낙타 타고 사막 안으로 들어가 텐트에서 하룻밤. 별이 쏟아지는 하늘은 평생 잊지 못할 장면입니다.', '58.231.101.14', '2026-04-10 19:00:00', 'africa', 'review', 'ACTIVE', 0, 0, 4, '2026-04-15 14:55:07', 0, NULL, NULL, NULL, NULL, 0),
	(15, 13, '인도 바라나시, 충격과 경이로움의 도시', '갠지스강 가트에서 본 아침 의식은 종교와 죽음과 삶이 공존하는 장면이었습니다. 인도 여행 중 가장 강렬한 경험. 위생은 포기하고 경험을 사야 하는 곳입니다.', '211.36.145.77', '2026-04-12 07:00:00', 'asia', 'review', 'ACTIVE', 0, 0, 4, '2026-04-15 14:55:08', 0, NULL, NULL, NULL, NULL, 0),
	(16, 2, '오사카 도톤보리 야식 투어 후기', '타코야키, 오코노미야키, 구시카츠까지. 도톤보리 한 블록만 걸어도 배가 터집니다. 글리코 간판 앞 사진은 기본 중의 기본. 밤 11시까지 신나게 먹었습니다.', '175.112.34.21', '2026-04-15 08:00:00', 'asia', 'review', 'ACTIVE', 2, 0, 4, '2026-04-22 00:57:34', 0, NULL, NULL, NULL, NULL, 0),
	(17, 7, '산토리니 오이아 일몰 사진 모음', '세상에서 가장 아름다운 일몰이라는 말이 과장이 아니었습니다. 파란 돔 지붕과 붉은 하늘이 만드는 풍경. 오후 5시부터 자리 잡아야 좋은 각도를 얻을 수 있습니다.', '220.85.67.43', '2026-04-15 10:00:00', 'europe', 'photo', 'ACTIVE', 5, 0, 4, '2026-04-26 18:37:57', 1, NULL, NULL, NULL, NULL, 0),
	(18, 9, '미국 팁 문화 완전 정복 가이드', '레스토랑 18~22%, 택시 15~20%, 호텔 하우스키핑 1~2달러/일. 처음엔 당황스럽지만 현지 서비스 노동자들의 생계와 직결됩니다. 계산서에 팁 포함 여부 꼭 확인하세요.', '110.47.22.88', '2026-04-15 12:00:00', 'north_america', 'tip', 'ACTIVE', 10, 1, 4, '2026-04-24 15:31:56', 0, NULL, NULL, NULL, 'money', 0),
	(19, 12, '파타고니아 W트레킹 5일 완주 후기', '칠레 토레스 델 파이네 W코스. 바람이 진짜 무서울 정도로 강합니다. 그래도 토레스 전망대에서 본 화강암 봉우리는 모든 고생을 잊게 만들었습니다.', '58.231.101.14', '2026-04-15 14:00:00', 'south_america', 'review', 'ACTIVE', 13, 1, 4, '2026-04-24 15:26:09', 1, NULL, NULL, NULL, NULL, 0),
	(20, 13, '뉴질랜드 밀포드사운드 크루즈, 비 오는 날이 더 아름답습니다', '비 오면 실망할 줄 알았는데 오히려 폭포가 수백 개 생겨 장관이었습니다. 피오르드 절벽에서 쏟아지는 물줄기. 퀸스타운에서 당일치기 가능하지만 전날 숙박 강력 추천합니다.', '211.36.145.77', '2026-04-15 16:00:00', 'oceania', 'review', 'ACTIVE', 17, 0, 4, '2026-04-26 18:37:50', 0, NULL, NULL, NULL, NULL, 0),
	(21, 7, '교토 3박 4일 여행: 감성과 인파 사이의 냉정한 기록', '1. 여행 개요\r\n일정: 2026년 4월 초 (3박 4일)\r\n\r\n목적: 주요 사찰 방문 및 로컬 맛집 탐방\r\n\r\n비용: 항공 및 숙박 제외, 현지 체류비 약 60만 원 (1인 기준)\r\n\r\n2. 방문지별 팩트 체크\r\n기요미즈데라 (청수사): * 장점: 압도적인 건축미와 시내 조망.\r\n\r\n단점: 오전 9시 이후 방문 시 \'사람 구경\'으로 변질됨. 사진 촬영이 불가능할 정도의 인파.\r\n\r\n팁: 반드시 개장 시간(오전 6시)에 맞춰 방문할 것을 권장함.\r\n\r\n아라시야마 치쿠린 (대나무 숲):\r\n\r\n현실: 소셜 미디어의 정적인 분위기와 달리 매우 번잡함. 대나무 숲 자체의 규모는 생각보다 작음.\r\n\r\n대안: 인근의 유료 사찰(텐류지 등) 내부 정원이 훨씬 정돈되어 있고 쾌적함.\r\n\r\n니시키 시장:\r\n\r\n의견: 길거리 음식을 즐기기에 좋으나 가격대가 관광지 프리미엄으로 인해 다소 높게 책정되어 있음. 가성비를 중시한다면 인근 골목의 일반 식당을 추천함.\r\n\r\n3. 종합 평가 및 주의사항\r\n교통 효율성: 교토 시내 버스는 정체가 심함. 가능하면 지하철과 도보를 조합하는 것이 시간 관리 측면에서 유리함.\r\n\r\n예약 필수: 구글 평점 4.5 이상의 식당은 예약 없이는 입장이 거의 불가능함. 무작정 대기하는 것은 시간 낭비임.\r\n\r\n날씨 변수: 일교차가 크므로 겹쳐 입을 수 있는 겉옷이 필수적임.\r\n\r\n4. 한 줄 평\r\n"철저한 사전 예약과 얼리버드 전략 없이는 \'휴식\'이 아닌 \'고행\'이 될 수 있는 도시. 하지만 계획대로 움직인다면 그만한 가치가 있음."', '0:0:0:0:0:0:0:1', '2026-04-16 04:16:29', 'asia', 'review', 'ACTIVE', 40, 2, 3, '2026-04-27 22:31:32', 0, NULL, NULL, NULL, NULL, 0),
	(22, 7, '강릉 1박 2일 런트립: 경포호수 코스 분석 및 로컬 맛집', '1. 코스 요약 (경포호수 한 바퀴)\r\n거리: 약 4.3km (평지 위주)\r\n\r\n노면 상태: 우수 (우레탄 및 평탄한 보도블록)\r\n\r\n한 줄 평: 초보부터 숙련자까지 케이던스 유지하며 뛰기 최적의 장소. 특히 새벽 시간대 인파가 적어 집중하기 좋음.\r\n\r\n2. 직접 경험한 로컬 맛집 (냉정한 평가)\r\n초당순두부 마을: * 현실: 유명한 곳은 웨이팅 1시간 이상. 맛의 차이가 크지 않으니 대기가 적은 인근 식당도 충분히 경쟁력 있음.\r\n\r\n추천: 짬뽕순두부보다는 기본 \'모두부\'와 \'순두부 전골\'이 원재료의 맛을 느끼기에 적합함.\r\n\r\n안목해변 카페거리:\r\n\r\n주의: 뷰는 좋으나 커피 품질(원두 선별 및 추출) 측면에서는 실망스러운 곳이 일부 있음. 테이크아웃 후 해변 산책을 권장.\r\n\r\n3. 여행 꿀팁\r\n숙소: 경포호수 인근 숙소를 잡으면 이른 아침 러닝 후 바로 샤워 가능. 동선 효율 극대화.\r\n\r\n준비물: 바닷바람이 강하므로 기능성 바람막이 필수.', '0:0:0:0:0:0:0:1', '2026-04-16 04:19:06', 'asia', 'review', 'BLOCKED', 34, 0, 0, '2026-04-22 07:44:24', 0, NULL, NULL, NULL, NULL, 0),
	(23, 7, '강릉 1박 2일 런트립: 경포호수 코스 분석 및 로컬 맛집', '1. 코스 요약 (경포호수 한 바퀴)\r\n거리: 약 4.3km (평지 위주)\r\n\r\n노면 상태: 우수 (우레탄 및 평탄한 보도블록)\r\n\r\n한 줄 평: 초보부터 숙련자까지 케이던스 유지하며 뛰기 최적의 장소. 특히 새벽 시간대 인파가 적어 집중하기 좋음.\r\n\r\n2. 직접 경험한 로컬 맛집 (냉정한 평가)\r\n초당순두부 마을: * 현실: 유명한 곳은 웨이팅 1시간 이상. 맛의 차이가 크지 않으니 대기가 적은 인근 식당도 충분히 경쟁력 있음.\r\n\r\n추천: 짬뽕순두부보다는 기본 \'모두부\'와 \'순두부 전골\'이 원재료의 맛을 느끼기에 적합함.\r\n\r\n안목해변 카페거리:\r\n\r\n주의: 뷰는 좋으나 커피 품질(원두 선별 및 추출) 측면에서는 실망스러운 곳이 일부 있음. 테이크아웃 후 해변 산책을 권장.\r\n\r\n3. 여행 꿀팁\r\n숙소: 경포호수 인근 숙소를 잡으면 이른 아침 러닝 후 바로 샤워 가능. 동선 효율 극대화.\r\n\r\n준비물: 바닷바람이 강하므로 기능성 바람막이 필수.', '0:0:0:0:0:0:0:1', '2026-04-16 04:19:09', 'asia', 'review', 'DELETED', 1, 0, 0, '2026-04-16 04:19:25', 0, NULL, NULL, NULL, NULL, 0),
