	(74, 131, 'fsdf', '<p><img src="https://res.cloudinary.com/dpwkbo5lk/image/upload/v1776954521/community/inline/jrktln75i6bra7whvsfk.png" style="width: 882.4px;"><img src="https://res.cloudinary.com/dpwkbo5lk/image/upload/v1776954491/community/inline/terafw97iciyhpawy3of.png" style="width: 882.4px;">asdfasdfsafdsadf</p><p><br></p><p><br></p><p><img src="https://res.cloudinary.com/dpwkbo5lk/image/upload/v1776954494/community/inline/dw3uhtkgokqlvitbpyzc.png" style="width: 882.4px;"></p><p><br></p>', '0:0:0:0:0:0:0:1', '2026-04-23 23:28:45', 'asia', 'photo', 'DELETED', 4, 0, 0, '2026-04-24 14:49:41', 0, NULL, NULL, NULL, NULL, 0),
	(75, 7, '복궁복궁', '<p>복궁이요</p>', '0:0:0:0:0:0:0:1', '2026-04-27 16:55:31', 'asia', 'question', 'ACTIVE', 17, 0, 2, '2026-04-27 22:34:08', 2, 1, '2026-04-27 16:58:03', 199, NULL, 0),
	(76, 7, '경복궁 추천 코스 있을까요?', '<p>1박 2일 일정으로 서울 가려는데 경복궁 등 추천 코스 있으시면 알려주세요</p>', '0:0:0:0:0:0:0:1', '2026-04-27 22:04:23', 'asia', 'question', 'DELETED', 6, 0, 1, '2026-04-27 22:27:24', 0, 1, '2026-04-27 22:05:45', 202, NULL, 0),
	(77, 7, '경복궁 추천 코스 있을까요???????', '<p>1박2일 일정으로 서울 가려는데 경복궁 등 추천 코스 있으시면 알려주세요</p><p><br></p>', '0:0:0:0:0:0:0:1', '2026-04-27 22:22:27', 'asia', 'question', 'DELETED', 6, 0, 1, '2026-04-27 22:27:19', 0, 1, '2026-04-27 22:23:30', 204, NULL, 0),
	(78, 7, '경복궁 여행 가려고 하는데 추천 부탁 드려요 (서울 1박 2일 여행이에요)', '<p>추천 부탁드려요&nbsp;</p>', '0:0:0:0:0:0:0:1', '2026-04-27 22:32:27', 'asia', 'question', 'DELETED', 6, 0, 1, '2026-04-28 00:36:05', 0, 1, '2026-04-27 22:33:40', 206, NULL, 0);
