	(47, '1fea95a2-4230-4c60-a880-217367eb9606', 'SPOT', 6, 'address', '태국 방콕', 'a4be4915be9787e2cb6902547af17b4b803b2ea73ee4465b66a0806fc0f17baa', 'en', 'Bangkok, Thailand', 'google-cloud-translation-v2', '2026-04-16 07:40:58', '2026-04-16 07:40:58'),
	(48, '41c3ce31-1741-4faf-9430-76f807070b2a', 'SPOT', 6, 'description', '활기 넘치는 태국의 수도. 화려한 사원, 맛있는 길거리 음식, 저렴한 쇼핑의 천국', '85f51872c647d9d78db6a3efea72989e31a7b3f4fd2cec1e62bb91248669b7b4', 'en', 'The vibrant capital of Thailand. A paradise of magnificent temples, delicious street food, and affordable shopping.', 'google-cloud-translation-v2', '2026-04-16 07:40:59', '2026-04-16 07:40:59'),
	(49, '2a2b8c17-d1b4-434b-87ed-c776420edecc', 'SPOT', 1, 'name', '도쿄', 'd0ce1d2834e9eefefba3d4f9f26ddbe28036099f3bdb09e53542cd2d72147b6a', 'en', 'Tokyo', 'google-cloud-translation-v2', '2026-04-16 07:40:59', '2026-04-16 07:40:59'),
