INSERT INTO `TRAVEL_PACKAGE` (`package_idx`, `seller_user_idx`, `spot_idx`, `package_title`, `package_summary`, `package_content`, `package_price`, `currency_code`, `start_date`, `end_date`, `min_people`, `max_people`, `package_status`, `reject_reason`, `main_image_path`, `view_count`, `like_count`, `booking_count`, `is_home_featured`, `home_featured_order`, `home_featured_start_at`, `home_featured_end_at`, `home_exposure_count`, `home_click_count`, `approved_by_user_idx`, `approved_at`, `created_at`, `updated_at`) VALUES
	(1, 3, 33, '동대문중 미식 패키지', '동대문중학교 미식 투어', '동대문중 짱짱맨', 44444, 'KRW', '2026-04-21', '2026-04-21', 1, NULL, 'APPROVED', NULL, 'https://mblogthumb-phinf.pstatic.net/MjAyNDA0MThfMTM3/MDAxNzEzNDExMjIyMzU4.CVwiHFeiTd5qyCvKS8PDEe9oYKMKRFfunzImX2M69Pcg.No9rVEyQiA202m0BXX7nwmpp5t9vuNtO3FvTzdPxCHwg.JPEG/1713411183371.jpg?type=w800', 0, 0, 0, 0, NULL, NULL, NULL, 0, 0, 14, '2026-04-21 08:53:50', '2026-04-21 07:45:13', '2026-04-22 03:47:46'),
	(24, 126, 1, '도쿄 감성 시티 투어 3일', '시부야, 아사쿠사, 도쿄타워를 한 번에 즐기는 도쿄 핵심 패키지', '도쿄의 대표 명소와 현지 맛집을 중심으로 구성한 2박 3일 여행 패키지입니다. 첫 방문자도 부담 없이 이동할 수 있도록 주요 동선을 압축했습니다.', 389000, 'KRW', '2026-05-10', '2026-08-31', 1, 12, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?w=1200&q=80', 320, 48, 17, 1, 1, '2026-04-23 07:06:08', '2026-08-31 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(25, 126, 2, '파리 낭만 미술관 투어 4일', '에펠탑 야경과 루브르, 오르세를 함께 즐기는 파리 문화 여행', '파리의 대표 미술관과 세느강 주변 명소를 중심으로 구성한 패키지입니다. 자유 시간과 가이드 투어를 적절히 섞어 여유로운 일정을 제공합니다.', 1290000, 'KRW', '2026-05-15', '2026-09-30', 1, 10, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?w=1200&q=80', 510, 92, 26, 1, 2, '2026-04-23 07:06:08', '2026-09-30 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(26, 126, 3, '발리 힐링 리조트 패키지 5일', '해변, 스파, 리조트 휴식을 중심으로 한 발리 힐링 여행', '발리의 리조트 숙박과 스파, 해변 자유 일정을 포함한 휴양형 패키지입니다. 관광보다 휴식에 초점을 맞춘 일정입니다.', 890000, 'KRW', '2026-06-01', '2026-10-31', 2, 16, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?w=1200&q=80', 450, 71, 22, 1, 3, '2026-04-23 07:06:08', '2026-10-31 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(27, 126, 4, '산토리니 선셋 허니문 5일', '하얀 마을과 에게해 일몰을 즐기는 감성 휴양 패키지', '산토리니의 대표 전망 포인트와 해변, 와이너리 일정을 포함한 프리미엄 감성 패키지입니다.', 1790000, 'KRW', '2026-06-10', '2026-09-20', 2, 8, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1570077188670-e3a8d69ac5ff?w=1200&q=80', 610, 118, 31, 1, 4, '2026-04-23 07:06:08', '2026-09-20 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(28, 126, 5, '뉴욕 브로드웨이 시티 패키지 4일', '타임스퀘어, 센트럴파크, 브로드웨이를 즐기는 뉴욕 핵심 일정', '뉴욕 대표 명소와 야경, 쇼핑 동선을 중심으로 구성한 도시형 패키지입니다. 선택 옵션으로 브로드웨이 공연 관람을 추가할 수 있습니다.', 1490000, 'KRW', '2026-05-20', '2026-11-30', 1, 14, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1485871981521-5b1fd3805eee?w=1200&q=80', 730, 134, 39, 1, 5, '2026-04-23 07:06:08', '2026-11-30 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(29, 126, 6, '방콕 야시장 미식 투어 3일', '왕궁, 야시장, 로컬 맛집을 중심으로 한 방콕 가성비 여행', '방콕의 주요 사원과 야시장, 로컬 식당을 함께 즐기는 실속형 패키지입니다. 짧은 일정으로 핵심만 경험할 수 있습니다.', 490000, 'KRW', '2026-05-05', '2026-10-15', 1, 20, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1508009603885-50cf7c579365?w=1200&q=80', 280, 39, 14, 1, 6, '2026-04-23 07:06:08', '2026-10-15 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(30, 3, 7, '바르셀로나 가우디 건축 투어 4일', '사그라다 파밀리아와 구엘공원을 중심으로 한 예술 여행', '가우디 건축물을 중심으로 바르셀로나의 예술과 해변 분위기를 함께 즐기는 패키지입니다.', 1190000, 'KRW', '2026-06-05', '2026-09-30', 1, 12, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1583422409516-2895a77efded?w=1200&q=80', 390, 63, 18, 0, NULL, '2026-04-23 07:06:08', '2026-09-30 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(31, 3, 9, '두바이 사막 사파리 패키지 4일', '부르즈 할리파와 사막 사파리를 함께 즐기는 두바이 여행', '두바이의 현대적인 도시 명소와 사막 사파리를 함께 구성한 액티비티 중심 패키지입니다.', 990000, 'KRW', '2026-05-25', '2026-12-31', 2, 15, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?w=1200&q=80', 360, 55, 16, 0, NULL, '2026-04-23 07:06:08', '2026-12-31 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(32, 3, 10, '프라하 중세 야경 투어 3일', '프라하성, 카를교, 구시가지를 걷는 동유럽 감성 여행', '프라하의 구시가지와 야경 명소를 중심으로 구성한 도보 여행 패키지입니다. 중세 도시 분위기를 깊게 느낄 수 있습니다.', 790000, 'KRW', '2026-05-18', '2026-10-31', 1, 10, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1519677100203-a0e668c92439?w=1200&q=80', 260, 41, 11, 0, NULL, '2026-04-23 07:06:08', '2026-10-31 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(33, 3, 11, '시드니 오페라하우스 해안 투어 5일', '오페라하우스, 하버브리지, 본다이비치를 즐기는 호주 여행', '시드니의 대표 랜드마크와 해변 일정을 함께 담은 패키지입니다. 도시 관광과 자연 풍경을 균형 있게 구성했습니다.', 1390000, 'KRW', '2026-06-15', '2026-12-15', 1, 12, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?w=1200&q=80', 310, 52, 13, 0, NULL, '2026-04-23 07:06:08', '2026-12-15 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(34, 126, 12, '교토 전통 문화 체험 3일', '기온 거리, 아라시야마, 전통 사찰을 둘러보는 교토 감성 여행', '교토의 전통 거리와 사찰, 대나무 숲을 중심으로 구성한 문화 체험형 패키지입니다.', 690000, 'KRW', '2026-05-12', '2026-11-10', 1, 10, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?w=1200&q=80', 470, 88, 24, 1, 7, '2026-04-23 07:06:08', '2026-11-10 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-23 07:06:08'),
	(35, 3, 26, '도쿄 디즈니랜드 원데이 패키지', '입장 동선과 인기 어트랙션 중심으로 즐기는 도쿄 디즈니랜드', '도쿄 디즈니랜드를 하루 동안 효율적으로 즐길 수 있도록 이동 동선과 추천 어트랙션을 포함한 테마파크 패키지입니다.', 230000, 'KRW', '2026-05-01', '2026-12-31', 1, 20, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1590144662036-33bf0ebd2c7f?w=1200&q=80', 520, 96, 28, 0, NULL, '2026-04-23 07:06:08', '2026-12-31 23:59:59', 0, 0, 6, '2026-04-23 07:06:08', '2026-04-23 07:06:08', '2026-04-27 18:37:43'),
	(36, 126, 1, '도쿄 로컬 골목 맛집 투어', '현지인이 자주 가는 이자카야와 라멘 골목을 중심으로 한 도쿄 미식 패키지', '도쿄의 유명 관광지보다 골목 맛집과 현지 분위기에 집중한 패키지입니다. 시부야, 신주쿠, 우에노 일대를 중심으로 부담 없이 즐길 수 있습니다.', 320000, 'KRW', '2026-05-08', '2026-09-30', 1, 10, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1554797589-7241bb691973?w=1200&q=80', 280, 44, 13, 1, 8, '2026-04-23 07:20:07', '2026-09-30 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(37, 126, 1, '도쿄 야경 포토 스팟 패키지', '도쿄타워, 롯폰기, 오다이바 야경을 담는 감성 사진 여행', '도쿄의 대표 야경 포인트를 중심으로 이동하며 사진 촬영에 적합한 시간대와 동선을 맞춘 패키지입니다.', 410000, 'KRW', '2026-05-15', '2026-10-31', 1, 8, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=1200&q=80', 360, 61, 16, 1, 9, '2026-04-23 07:20:07', '2026-10-31 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(38, 126, 2, '파리 카페 산책 패키지', '몽마르트르와 세느강 주변 카페를 여유롭게 걷는 파리 감성 일정', '파리의 대표 카페 거리와 산책 코스를 중심으로 구성한 여유형 패키지입니다. 빠듯한 관광보다 분위기와 휴식에 집중합니다.', 980000, 'KRW', '2026-06-01', '2026-11-30', 1, 8, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1499856871958-5b9627545d1a?w=1200&q=80', 410, 75, 19, 1, 10, '2026-04-23 07:20:07', '2026-11-30 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(39, 3, 2, '파리 야경 세느강 패키지', '에펠탑 야경과 세느강 주변 산책을 중심으로 한 파리 밤 여행', '해질녘부터 밤까지 파리의 대표 야경 코스를 둘러보는 패키지입니다. 커플 여행과 감성 사진 여행에 적합합니다.', 1120000, 'KRW', '2026-05-20', '2026-12-20', 1, 12, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1431274172761-fca41d930114?w=1200&q=80', 520, 98, 24, 0, NULL, '2026-04-23 07:20:07', '2026-12-20 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(40, 126, 3, '발리 우붓 정글 힐링 패키지', '우붓 숲과 스파, 요가 체험을 포함한 발리 힐링 여행', '발리 우붓 지역의 자연과 휴식을 중심으로 구성한 패키지입니다. 리조트 휴식, 요가, 스파 체험을 포함합니다.', 760000, 'KRW', '2026-05-25', '2026-10-31', 2, 14, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?w=1200&q=80', 390, 67, 21, 1, 11, '2026-04-23 07:20:07', '2026-10-31 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(41, 3, 3, '발리 해변 선셋 패키지', '스미냑과 짐바란 해변에서 즐기는 발리 석양 여행', '발리의 해변과 선셋 명소를 중심으로 구성한 휴양형 패키지입니다. 바다 전망 식사와 자유 시간을 포함합니다.', 820000, 'KRW', '2026-06-05', '2026-12-31', 2, 16, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=80', 430, 72, 20, 0, NULL, '2026-04-23 07:20:07', '2026-12-31 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(42, 126, 4, '산토리니 와이너리 투어', '에게해 풍경과 현지 와인을 함께 즐기는 산토리니 프리미엄 일정', '산토리니의 전망 좋은 와이너리와 일몰 포인트를 연결한 감성 패키지입니다. 여유로운 일정과 사진 스팟을 포함합니다.', 1680000, 'KRW', '2026-06-10', '2026-10-10', 2, 8, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1533105079780-92b9be482077?w=1200&q=80', 500, 101, 27, 1, 12, '2026-04-23 07:20:07', '2026-10-10 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(43, 3, 4, '산토리니 블루돔 포토 투어', '이아 마을과 블루돔을 중심으로 한 산토리니 사진 여행', '산토리니의 대표 포토 스팟을 중심으로 구성한 패키지입니다. 일몰 시간대에 맞춰 주요 동선을 배치했습니다.', 1580000, 'KRW', '2026-05-30', '2026-09-30', 1, 8, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1613395877344-13d4a8e0d49e?w=1200&q=80', 470, 89, 22, 0, NULL, '2026-04-23 07:20:07', '2026-09-30 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(44, 126, 5, '뉴욕 미술관 감성 투어', '모마와 메트로폴리탄을 중심으로 한 뉴욕 문화 여행', '뉴욕의 대표 미술관과 센트럴파크 산책을 함께 구성한 문화형 패키지입니다. 도시의 감성과 예술을 함께 경험할 수 있습니다.', 1320000, 'KRW', '2026-05-18', '2026-11-30', 1, 10, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1534430480872-3498386e7856?w=1200&q=80', 610, 110, 30, 1, 13, '2026-04-23 07:20:07', '2026-11-30 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(45, 3, 5, '뉴욕 쇼핑 앤 야경 패키지', '소호 쇼핑과 브루클린 브릿지 야경을 담은 뉴욕 일정', '뉴욕의 쇼핑 명소와 야경 명소를 연결한 도시형 패키지입니다. 자유 일정과 추천 동선을 함께 제공합니다.', 1260000, 'KRW', '2026-06-01', '2026-12-31', 1, 12, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1490644658840-3f2e3f8c5625?w=1200&q=80', 540, 95, 25, 0, NULL, '2026-04-23 07:20:07', '2026-12-31 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(46, 126, 6, '방콕 왕궁 사원 투어', '왕궁, 왓포, 왓아룬을 중심으로 한 방콕 전통 문화 일정', '방콕의 대표 사원과 왕궁을 중심으로 구성한 문화형 패키지입니다. 짧은 일정으로 방콕의 핵심 명소를 볼 수 있습니다.', 430000, 'KRW', '2026-05-05', '2026-10-31', 1, 18, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1528181304800-259b08848526?w=1200&q=80', 300, 50, 15, 1, 14, '2026-04-23 07:20:07', '2026-10-31 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(47, 3, 6, '방콕 루프탑 나이트 패키지', '야시장과 루프탑 바를 함께 즐기는 방콕 밤 여행', '방콕의 야시장, 로컬 맛집, 루프탑 전망을 중심으로 구성한 나이트 패키지입니다.', 520000, 'KRW', '2026-06-01', '2026-11-30', 1, 14, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1563492065599-3520f775eeed?w=1200&q=80', 340, 58, 18, 0, NULL, '2026-04-23 07:20:07', '2026-11-30 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(48, 126, 7, '바르셀로나 해변 자유 패키지', '가우디 건축과 바르셀로네타 해변을 함께 즐기는 자유 일정', '바르셀로나의 예술 명소와 해변 휴식을 균형 있게 배치한 패키지입니다. 도시 관광과 자유 시간을 모두 포함합니다.', 1080000, 'KRW', '2026-05-20', '2026-10-20', 1, 12, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1539037116277-4db20889f2d4?w=1200&q=80', 420, 73, 19, 1, 15, '2026-04-23 07:20:07', '2026-10-20 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(49, 3, 7, '바르셀로나 타파스 미식 투어', '고딕지구와 타파스 맛집을 중심으로 한 바르셀로나 미식 여행', '바르셀로나의 골목과 타파스 맛집을 중심으로 구성한 미식형 패키지입니다. 현지 분위기를 느끼기 좋습니다.', 940000, 'KRW', '2026-06-12', '2026-11-15', 1, 10, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1558642452-9d2a7deb7f62?w=1200&q=80', 330, 62, 16, 0, NULL, '2026-04-23 07:20:07', '2026-11-15 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(50, 126, 9, '두바이 럭셔리 시티 패키지', '부르즈 할리파, 팜 주메이라, 두바이몰을 포함한 도시 여행', '두바이의 대표 랜드마크와 쇼핑 명소를 중심으로 구성한 고급 도시형 패키지입니다.', 1160000, 'KRW', '2026-05-25', '2026-12-31', 2, 12, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1526495124232-a04e1849168c?w=1200&q=80', 460, 82, 23, 1, 16, '2026-04-23 07:20:07', '2026-12-31 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(51, 3, 9, '두바이 사막 캠프 체험', '사막 사파리와 캠프 디너를 포함한 두바이 액티비티 패키지', '두바이 사막에서 즐기는 사파리, 낙타 체험, 캠프 디너를 중심으로 구성한 액티비티 패키지입니다.', 870000, 'KRW', '2026-06-05', '2026-12-20', 2, 18, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=1200&q=80', 390, 68, 20, 0, NULL, '2026-04-23 07:20:07', '2026-12-20 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(52, 126, 10, '프라하 클래식 음악 여행', '프라하성과 클래식 공연을 함께 즐기는 동유럽 감성 패키지', '프라하의 역사 명소와 클래식 공연 관람을 함께 구성한 문화형 패키지입니다.', 860000, 'KRW', '2026-05-15', '2026-10-31', 1, 8, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1541849546-216549ae216d?w=1200&q=80', 310, 57, 14, 1, 17, '2026-04-23 07:20:07', '2026-10-31 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-28 11:15:03'),
	(53, 3, 10, '프라하 맥주 골목 투어', '구시가지와 현지 펍을 중심으로 한 프라하 로컬 여행', '프라하의 골목길과 현지 펍 문화를 함께 즐기는 패키지입니다. 자유로운 분위기의 소규모 여행에 적합합니다.', 720000, 'KRW', '2026-06-01', '2026-11-30', 1, 10, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1519677100203-a0e668c92439?w=1200&q=80', 270, 43, 12, 0, NULL, '2026-04-23 07:20:07', '2026-11-30 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-28 09:06:16'),
	(54, 126, 11, '시드니 블루마운틴 데이투어', '시드니 근교 블루마운틴과 오페라하우스를 함께 즐기는 일정', '시드니 시내 명소와 근교 자연 명소를 함께 구성한 패키지입니다. 도시와 자연을 모두 보고 싶은 여행자에게 적합합니다.', 1280000, 'KRW', '2026-05-22', '2026-12-15', 1, 12, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1528072164453-f4e8ef0d475a?w=1200&q=80', 350, 64, 17, 1, 18, '2026-04-23 07:20:07', '2026-12-15 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(55, 3, 12, '교토 사찰 산책 패키지', '기요미즈데라, 기온, 아라시야마를 여유롭게 걷는 교토 일정', '교토의 대표 사찰과 전통 거리를 중심으로 구성한 산책형 패키지입니다. 일본 전통 분위기를 느끼기 좋습니다.', 640000, 'KRW', '2026-05-10', '2026-11-30', 1, 10, 'APPROVED', NULL, 'https://images.unsplash.com/photo-1528360983277-13d401cdc186?w=1200&q=80', 430, 86, 21, 0, NULL, '2026-04-23 07:20:07', '2026-11-30 23:59:59', 0, 0, 6, '2026-04-23 07:20:07', '2026-04-23 07:20:07', '2026-04-23 07:20:07'),
	(56, 124, 9, '진짜 리얼 두쫀쿠', '리얼 두쫀쿠 제작 투어', '두바이에서 두쫀쿠 만들겁니다.', 10000, 'KRW', '2026-04-29', '2026-04-30', 10, 30, 'PENDING', NULL, NULL, 0, 0, 0, 0, NULL, NULL, NULL, 0, 0, NULL, NULL, '2026-04-27 15:52:11', '2026-04-27 15:52:11'),
